import{_ as e,o as s,c as t,a2 as o}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"巧言","description":"","frontmatter":{"title":"巧言","date":"2026-11-08T00:00:00.000Z","seq":38,"categories":["美文","诗经"],"collection":"《诗经 · 小雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·小雅/巧言.md","filePath":"blogs/诗经·小雅/巧言.md"}'),p={name:"blogs/诗经·小雅/巧言.md"};function r(c,a,l,n,_,i){return s(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="巧言" tabindex="-1">巧言 <a class="header-anchor" href="#巧言" aria-label="Permalink to &quot;巧言&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　节南山之什</p><div class="poem"><p class="poem-stanza">悠悠昊天，曰父母且。无罪无辜，乱如此幠。昊天已威，予慎无罪。昊天大幠，予慎无辜。</p><p class="poem-stanza">乱之初生，僭始既涵。乱之又生，君子信谗。君子如怒，乱庶遄沮。君子如祉，乱庶遄已。</p><p class="poem-stanza">君子屡盟，乱是用长。君子信盗，乱是用暴。盗言孔甘，乱是用餤。匪其止共，维王之邛。</p><p class="poem-stanza">奕奕寝庙，君子作之。秩秩大猷，圣人莫之。他人有心，予忖度之。跃跃毚兔，遇犬获之。</p><p class="poem-stanza">荏染柔木，君子树之。往来行言，心焉数之。蛇蛇硕言，出自口矣。巧言如簧，颜之厚矣。</p><p class="poem-stanza">彼何人斯？居河之麋。无拳无勇，职为乱阶。既微且尰，尔勇伊何？为犹将多，尔居徒几何？</p></div>',3)])])}const u=e(p,[["render",r]]);export{d as __pageData,u as default};
